{"implementation": "def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    last = attempts[-1]
    if last['success'] or len(attempts) >= max_attempts:
        return {
            'decision': 'finalize',
            'memory_append': None,
            'next_attempt': -1
        }
    else:
        return {
            'decision': 'retry',
            'memory_append': {
                'reflection': last['reflection'],
                'signature': last['failure_signature']
            },
            'next_attempt': len(attempts)
        }"}
